import{_ as t,c as a,o as r,a5 as o}from"./chunks/framework.DorIfSpC.js";const m=JSON.parse('{"title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","frontmatter":{"layout":"home","title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","hero":{"name":"星智未來","text":"以 AI 工程，快速把點子變成價值","tagline":"我們分享實戰筆記、專案故事與教學，持續更新。","actions":[{"theme":"brand","text":"AI 文章","link":"/ai/"},{"theme":"alt","text":"機器人文章","link":"/robot/"},{"theme":"alt","text":"專案文章","link":"/project/"}]},"features":[{"title":"AI","details":"最新 AI 技術與應用分享。","link":"/ai/"},{"title":"機器人","details":"機器人最新發展","link":"/robot/"},{"title":"專案","details":"我們的專案展示與經驗分享。","link":"/project/"},{"title":"學習","details":"長期學習路徑的筆記與心得。","link":"/learning/"}],"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"name":"twitter:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"property":"og:title","content":"星智未來 | 星智未來"}],["meta",{"name":"twitter:title","content":"星智未來 | 星智未來"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1790609528000}'),i={name:"index.md"};function n(l,e,c,s,h,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="📝-最新文章" tabindex="-1">📝 最新文章 <a class="header-anchor" href="#📝-最新文章" aria-label="Permalink to &quot;📝 最新文章&quot;">​</a></h2><h3 id="jackie-的身高-我改了兩次" tabindex="-1"><a href="/project/h3-reference-boards">Jackie 的身高，我改了兩次</a> <a class="header-anchor" href="#jackie-的身高-我改了兩次" aria-label="Permalink to &quot;[Jackie 的身高，我改了兩次](/project/h3-reference-boards)&quot;">​</a></h3><p><strong>專案</strong> · 2026-09-28</p><p>一場教會的戲拍了兩版，問題九成不在提示詞，而在給 H3 的那張「板」：遠景換臉、用程式依身高縮放、先做灰模再生板、同一組輸入比五個圖像模型。模型不看劇本，它看板。</p><hr><h3 id="我說「要有喜感」-模型要的是兩個時間戳" tabindex="-1"><a href="/project/h3-director-vs-model">我說「要有喜感」，模型要的是兩個時間戳</a> <a class="header-anchor" href="#我說「要有喜感」-模型要的是兩個時間戳" aria-label="Permalink to &quot;[我說「要有喜感」，模型要的是兩個時間戳](/project/h3-director-vs-model)&quot;">​</a></h3><p><strong>專案</strong> · 2026-09-18</p><p>把 H3 的接線自動化之後，一輪從一天變成二十五分鐘，我才敢給第十條筆記。然後發現導演真正的工作是翻譯：我給的是意圖，模型要的是狀態和時間戳。</p><hr><h3 id="快了兩倍多-然後我發現自己量錯了四次" tabindex="-1"><a href="/project/minimax-h3-8step-acceleration">快了兩倍多，然後我發現自己量錯了四次</a> <a class="header-anchor" href="#快了兩倍多-然後我發現自己量錯了四次" aria-label="Permalink to &quot;[快了兩倍多，然後我發現自己量錯了四次](/project/minimax-h3-8step-acceleration)&quot;">​</a></h3><p><strong>專案</strong> · 2026-09-02</p><p>MiniMax H3 的 8 步蒸餾 LoRA 實測：兩次獨立量測快 2.1 到 2.6 倍，大動態下看不出劣化。但真正花時間的是搞清楚數字算不算數——四次量錯，四種不同的污染源。</p><hr><h3 id="為什麼每天摸一下貓的頭-是一件宇宙學意義的事" tabindex="-1"><a href="/project/migato-cosmic-ritual">為什麼每天摸一下貓的頭，是一件宇宙學意義的事</a> <a class="header-anchor" href="#為什麼每天摸一下貓的頭-是一件宇宙學意義的事" aria-label="Permalink to &quot;[為什麼每天摸一下貓的頭，是一件宇宙學意義的事](/project/migato-cosmic-ritual)&quot;">​</a></h3><p><strong>專案</strong> · 2026-03-20</p><p>從易經到塔羅，人類花了三千年設計觀測工具。Migato 米果把這套古老的儀式，變成每天早上摸一下頭的動作——讓你帶著意圖出門。</p><hr><h3 id="那張-ai-影片比價表-少了一列" tabindex="-1"><a href="/project/ai-video-cost-selfhost">那張 AI 影片比價表，少了一列</a> <a class="header-anchor" href="#那張-ai-影片比價表-少了一列" aria-label="Permalink to &quot;[那張 AI 影片比價表，少了一列](/project/ai-video-cost-selfhost)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-22</p><p>社群流傳的 AI 影片比價表有八個方案，就是沒有自架那一列。用兩週的實測數字補上去：同一個模型自己跑，比官方 API 便宜 4.9 倍，年費零。</p><hr>',21)])])}const f=t(i,[["render",n]]);export{m as __pageData,f as default};
